using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using EDJP.Observatory;class Program{static void Main(){var visits=new List<object>();foreach(bool batch in new[]{false,true})foreach(bool preread in new[]{false,true})foreach(int maximum in new[]{0,1,2,1000}){var e=new Evaluator.Evaluator();e.Core.IsLogMonitorBatchReading=batch;e.isPreReading=preread;e.settings.MaxSystems=maximum;foreach(ulong address in new ulong[]{1,2,1})e.SetCurrentSystem("System "+address,address,DateTime.UnixEpoch.AddSeconds((int)address));visits.Add(new{batch,preread,maximum,addresses=e.systems.Select(s=>s.SystemAddress).ToArray(),current=e.current.SystemAddress,messages=e.Core.Messages.ToArray()});}var totals=new List<object>();foreach(long current in new long[]{0,12345,100000})foreach(long total in new long[]{-1,0,10,12345,99999,100000,300000})foreach(int flag in new[]{-1,0,1}){var e=new Evaluator.Evaluator();e.current.TotalValue=current;var payload=new Dictionary<string,object>{{"Total",total}};if(flag!=-1)payload.Add("SubtractCurrent",flag==1);e.HandleEvaluatorSetTotal(new MessageSender(),payload);totals.Add(new{current,total,flag,unsold=e.UnsoldTotal,display=e.UnsoldTotal+current});}var sale=new Evaluator.Evaluator();sale.UnsoldTotal=20000;sale.current.TotalValue=12345;sale.Delete();Console.Write(JsonSerializer.Serialize(new{visits,totals,afterDelete=new{unsold=sale.UnsoldTotal,current=sale.current.TotalValue,display=sale.UnsoldTotal+sale.current.TotalValue}}));}}